input.replace:
test("leaves a value inside the range alone", () => {
  assert.equal(clamp(5, 0, 10), 5);
});

test("returns low when value is below range", () => {
  assert.equal(clamp(-3, 0, 10), 0);
});

test("returns high when value is above range", () => {
  assert.equal(clamp(13, 0, 10), 10);
});

test("returns low when value equals low", () => {
  assert.equal(clamp(0, 0, 10), 0);
});

test("returns high when value equals high", () => {
  assert.equal(clamp(10, 0, 10), 10);
});
